function translateMarkup(markup){if(window.appLanguage!=='en')return markup;const translated=Object.keys(EN).sort((a,b)=>b.length-a.length).reduce((out,zh)=>out.split(zh).join(EN[zh]),markup);return translated.replace(/[\u4e00-\u9fff]+/g,'')}
